    direction: new THREE.Vector3(0, 0, 1),
    yaw: 0,
    turnTimer: 0,
    speed: 1,
    moveSpeed: 1,
    detectRange: 11,
    attackDamage: 3,
    attackCooldown: 1,
    attackTimer: 0,
    halfHeight,
    bobSeed: 0,
    fedTimer: 0,
    ageTimer: 0
  };
}

function makeState(world: VoxelWorld, mobs: MobState[] = []): GameState {
  return {
    world,
    mobs,
    projectiles: [],
    nextProjectileId: 1,
